fn factory():
    fn local(a:int,/,b:int=2,*,c:int=3)->int:
        return a+b+c
    return local
f=factory()
x=f(1,c=4)

fn factory():
    fn local(a:int,/)->int:
        return a
    return local
f=factory()
f(a=1)

