record Box[T]:
    value:T
    fn apply[F](self,callback:F(T))->F.Result:
        return callback(self.value)
x=Box(3).apply(fn(item)=>item+1)

record R:
    value:int
    fn change(mut self)->int:
        self.value+=1
        return self.value
    fn writer(self):
        return fn()=>self.change()

record R:
    value:int
    fn change(mut self)->int:
        self.value+=1
        return self.value
    fn writer(self):
        return fn [mut self]()=>self.change()

record R:
    callback:callable()->int
    fn call(self)->int:
        return self.callback()

fn outer[T](value:T):
    fn local(other:T)->T:
        return other
    return local
f=outer(1)
x=f(2)

fn outer():
    fn local[T](value:T)->T:
        return value
    return local

fn outer():
    fn local()->int:
        break
        return 1
    return local
